-- Operational consultation extension. 061 history remains synthetic and immutable.
-- No activation, credentials or external requests are created by this migration.
begin;
alter table erp_fiscal_reconciliation.attempt add column profile text not null default 'synthetic-protocol-reconciliation-v1' check(profile in('synthetic-protocol-reconciliation-v1','sefaz-sp-protocol-homologation-v1'));
create function erp_fiscal_reconciliation.flags(p_profile text) returns jsonb language plpgsql immutable set search_path=pg_catalog as $$begin
 if p_profile='synthetic-protocol-reconciliation-v1' then return erp_fiscal_reconciliation.flags();end if;
 if p_profile is distinct from 'sefaz-sp-protocol-homologation-v1' then raise exception 'reconciliation_profile_invalid' using errcode='22023';end if;
 return erp_fiscal_reconciliation.flags()||jsonb_build_object('profile',p_profile,'origin','operational');end$$;
create function erp_fiscal_reconciliation.require_profile(p_id uuid,p_profile text,p_command boolean default false) returns erp_fiscal_reconciliation.attempt language plpgsql stable set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;begin
 select * into a from erp_fiscal_reconciliation.attempt where (not p_command and id=p_id)or(p_command and command_id=p_id);
 if not found then raise exception 'reconciliation_not_found' using errcode='P0002';end if;
 if a.profile is distinct from p_profile then raise exception 'reconciliation_profile_conflict' using errcode='40001';end if;return a;end$$;

create or replace function erp_fiscal_reconciliation.context(a erp_fiscal_reconciliation.attempt)returns jsonb language sql stable set search_path=pg_catalog as $$select jsonb_build_object(
 'attempt_id',a.id,'command_id',a.command_id,'actor',a.actor,'lease_id',a.lease_id,'nonce',a.nonce,'expires_at',a.expires_at,
 'purpose',a.profile,'binding_profile','sp-protocol-soap12-reviewed-v1','environment','2','model',a.model,'method','POST',
 'endpoint',replace(erp_fiscal_wsdl.endpoint(a.model,'protocol'),'?WSDL',''),'identity_version',a.identity_version,'issuer_cnpj',a.issuer_cnpj,
 'a1_version',a.a1_version,'credential_id',a.credential_id,'envelope_hash',a.envelope_hash,'certificate_fingerprint',a.certificate_fingerprint,
 'candidate_id',a.candidate_id,'signed_hash',a.signed_hash,'signed_size',a.signed_size,'access_key',a.access_key,'reference_digest',a.reference_digest,
 'request_hash',a.request_hash,'request_size',a.request_size)$$;
create or replace function erp_fiscal_reconciliation.view(a erp_fiscal_reconciliation.attempt)returns jsonb language sql stable set search_path=pg_catalog as $$select erp_fiscal_reconciliation.flags(a.profile)||jsonb_build_object('command_id',a.command_id,'receipt',(select receipt from erp_fiscal_reconciliation.command where id=a.command_id),'current',erp_fiscal_reconciliation.current(a),'error_code',a.error_code,
 'artifact',(select jsonb_build_object('response_hash',response_hash,'size_bytes',size_bytes,'evidence',evidence,'created_at',created_at)from erp_fiscal_reconciliation.artifact where attempt_id=a.id),
 'recovery',jsonb_build_object('private_executor_only',true,'context',erp_fiscal_reconciliation.context(a)))$$;
alter function erp_fiscal_reconciliation.validate_evidence(jsonb,text,text) rename to validate_synthetic_evidence;
create function erp_fiscal_reconciliation.validate_evidence(v jsonb,request_hash text,response_hash text)returns void language plpgsql immutable set search_path=pg_catalog as $$declare t jsonb;client jsonb;tls jsonb;begin
 if v->>'origin'='synthetic' then perform erp_fiscal_reconciliation.validate_synthetic_evidence(v,request_hash,response_hash);return;end if;
 if v->>'origin' is distinct from 'operational' or v->'tls_origin_verified' is distinct from 'true'::jsonb or jsonb_typeof(v->'transport_receipt_hash') is distinct from 'string' or v->>'transport_receipt_hash'!~'^[a-f0-9]{64}$' or jsonb_typeof(v->'transport_receipt_size') is distinct from 'number' or v->>'transport_receipt_size'!~'^[0-9]+$' or (v->>'transport_receipt_size')::numeric not between 1 and 8192 then raise exception 'reconciliation_transport_invalid' using errcode='22023';end if;
 perform erp_fiscal_reconciliation.validate_synthetic_evidence((v-array['transport_receipt_hash','transport_receipt_size','transport'])||jsonb_build_object('origin','synthetic','tls_origin_verified',false),request_hash,response_hash);
 t:=v->'transport';tls:=t->'tls';client:=t->'client';
 if not erp_a1.exact(t,array['profile','attempt_id','request_hash','response_hash','response_size','endpoint_id','received_at','tls','client']) or t->>'profile' is distinct from 'sefaz-sp-protocol-transport-v1' or jsonb_typeof(t->'attempt_id') is distinct from 'string' or t->>'attempt_id'!~'^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$' or t->>'request_hash' is distinct from request_hash or t->>'response_hash' is distinct from response_hash or jsonb_typeof(t->'response_size') is distinct from 'number' or t->>'response_size'!~'^[0-9]+$' or (t->>'response_size')::numeric not between 1 and 512000 or jsonb_typeof(t->'endpoint_id') is distinct from 'string' or t->>'endpoint_id' not in('sp-nfe-protocol-homologation','sp-nfce-protocol-homologation') or not erp_a1.iso(t->'received_at') then raise exception 'reconciliation_transport_invalid' using errcode='22023';end if;
 if not erp_a1.exact(tls,array['protocol','server_identity_verified','server_trust_profile','server_trust_anchor_sha256']) or jsonb_typeof(tls->'protocol') is distinct from 'string' or tls->>'protocol' not in('TLSv1.2','TLSv1.3') or tls->'server_identity_verified' is distinct from 'true'::jsonb or tls->>'server_trust_profile' is distinct from 'node-bundled-plus-iti-ssl-v10-20261016' or tls->>'server_trust_anchor_sha256' is distinct from '6e0bff069a26994c15de2c4888cc54af84882e5495b7fbf66be9ccffec7489f6' then raise exception 'reconciliation_tls_invalid' using errcode='22023';end if;
 if not erp_a1.exact(client,array['certificate_fingerprint','client_auth_usage','presented_chain_links_checked','icp_brasil_chain_validated','revocation_checked','a1_policy_verified']) or jsonb_typeof(client->'certificate_fingerprint') is distinct from 'string' or client->>'certificate_fingerprint'!~'^[a-f0-9]{64}$' or jsonb_typeof(client->'client_auth_usage') is distinct from 'string' or client->>'client_auth_usage' not in('unrestricted_absent','explicit_client_auth','unrestricted_any') or client->'presented_chain_links_checked' is distinct from 'true'::jsonb or client->'icp_brasil_chain_validated' is distinct from 'false'::jsonb or client->'revocation_checked' is distinct from 'false'::jsonb or client->'a1_policy_verified' is distinct from 'false'::jsonb then raise exception 'reconciliation_client_invalid' using errcode='22023';end if;
end$$;
alter function public.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer) set schema erp_fiscal_reconciliation;
alter function erp_fiscal_reconciliation.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer) rename to use_core;
create function public.erp_fiscal_reconciliation_use(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_request_hash text,p_request_size integer)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$begin perform erp_a1.access(p_user_id);perform erp_fiscal_reconciliation.require_profile(p_attempt_id,'synthetic-protocol-reconciliation-v1',false);return erp_fiscal_reconciliation.use_core(p_user_id,p_attempt_id,p_lease_id,p_request_hash,p_request_size);end$$;
alter function public.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb) set schema erp_fiscal_reconciliation;
alter function erp_fiscal_reconciliation.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb) rename to finish_core;
create function public.erp_fiscal_reconciliation_finish(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_response_hash text,p_response_size integer,p_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$begin perform erp_a1.access(p_user_id);perform erp_fiscal_reconciliation.require_profile(p_attempt_id,'synthetic-protocol-reconciliation-v1',false);if p_evidence->>'origin' is distinct from 'synthetic' then raise exception 'reconciliation_profile_conflict' using errcode='40001';end if;return erp_fiscal_reconciliation.finish_core(p_user_id,p_attempt_id,p_lease_id,p_response_hash,p_response_size,p_evidence);end$$;
alter function public.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text) set schema erp_fiscal_reconciliation;
alter function erp_fiscal_reconciliation.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text) rename to fail_core;
create function public.erp_fiscal_reconciliation_fail(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_error_code text)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$begin perform erp_a1.access(p_user_id);perform erp_fiscal_reconciliation.require_profile(p_attempt_id,'synthetic-protocol-reconciliation-v1',false);return erp_fiscal_reconciliation.fail_core(p_user_id,p_attempt_id,p_lease_id,p_error_code);end$$;
alter function public.erp_fiscal_reconciliation_command(uuid,uuid) set schema erp_fiscal_reconciliation;
alter function erp_fiscal_reconciliation.erp_fiscal_reconciliation_command(uuid,uuid) rename to command_core;
create function public.erp_fiscal_reconciliation_command(p_user_id uuid,p_command_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$begin perform erp_a1.access(p_user_id);perform erp_fiscal_reconciliation.require_profile(p_command_id,'synthetic-protocol-reconciliation-v1',true);return erp_fiscal_reconciliation.command_core(p_user_id,p_command_id);end$$;
create function public.erp_fiscal_protocol_begin(p_user_id uuid,p_command_id uuid,p_candidate_id uuid,p_signed_hash text,p_expected_identity_version integer,p_expected_a1_version integer,p_confirmed boolean)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare h erp_a1.head;c erp_a1.credential;a erp_fiscal_reconciliation.attempt;cmd erp_fiscal_reconciliation.command;s jsonb;tag text;at timestamptz;begin
 perform erp_a1.access(p_user_id);if p_command_id is null or p_candidate_id is null or p_signed_hash is null or p_signed_hash!~'^[a-f0-9]{64}$'or p_expected_identity_version is null or p_expected_identity_version<1 or p_expected_a1_version is null or p_expected_a1_version<1 or p_confirmed is distinct from true then raise exception'reconciliation_begin_invalid'using errcode='22023';end if;
 tag:=erp_fiscal_wsdl.hash(jsonb_build_object('actor',p_user_id,'candidate',p_candidate_id,'signed_hash',p_signed_hash,'identity_version',p_expected_identity_version,'a1_version',p_expected_a1_version,'confirmed',true,'profile','sefaz-sp-protocol-homologation-v1'));
 h:=erp_fiscal_reconciliation.locks(p_user_id,p_command_id);s:=erp_fiscal_reconciliation.source(p_user_id,p_candidate_id,p_signed_hash);select *into cmd from erp_fiscal_reconciliation.command where id=p_command_id;
 if found then
  if cmd.actor<>p_user_id or cmd.request_hash<>tag then raise exception'reconciliation_command_conflict'using errcode='40001';end if;select *into a from erp_fiscal_reconciliation.attempt where id=cmd.attempt_id for update;
  if a.state<>'prepared'or a.expires_at<=clock_timestamp()then return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true,'execution',null);end if;
  c:=erp_fiscal_reconciliation.check_a1(a,h);return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',true,'execution',erp_fiscal_reconciliation.execution(a,c));
 end if;
 c:=erp_fiscal_wsdl.check_a1(h,p_expected_identity_version,p_expected_a1_version);at:=clock_timestamp();
 if s->>'issuer_cnpj'is distinct from c.context->>'holder_cnpj'then raise exception'reconciliation_issuer_conflict'using errcode='40001';end if;
 insert into erp_fiscal_reconciliation.attempt(id,command_id,actor,candidate_id,signed_hash,signed_size,access_key,reference_digest,model,issuer_cnpj,identity_version,a1_version,credential_id,envelope_hash,certificate_fingerprint,state,lease_id,nonce,expires_at,created_at,profile)
 values(gen_random_uuid(),p_command_id,p_user_id,p_candidate_id,p_signed_hash,(s->>'signed_size')::integer,s->>'access_key',s->>'reference_digest',s->>'model',s->>'issuer_cnpj',p_expected_identity_version,h.version,h.credential_id,h.object_hash,c.metadata->>'fingerprint_sha256','prepared',gen_random_uuid(),gen_random_uuid(),at+interval'60 seconds',at,'sefaz-sp-protocol-homologation-v1')returning *into a;
 insert into erp_fiscal_reconciliation.command(id,actor,request_hash,attempt_id,receipt,created_at)values(p_command_id,p_user_id,tag,a.id,(s-array['access_key','reference_digest','issuer_cnpj'])||jsonb_build_object('attempt_id',a.id,'ordinal',a.ordinal,'command_id',p_command_id,'profile','sefaz-sp-protocol-homologation-v1','environment','2','identity_version',a.identity_version,'a1_version',a.a1_version,'confirmed',true,'created_at',at),at);
 insert into erp_fiscal_reconciliation.audit(attempt_id,actor,action)values(a.id,p_user_id,'prepare');
 if a.expires_at<=clock_timestamp()then raise exception'reconciliation_lease_expired'using errcode='40001';end if;
 return erp_fiscal_reconciliation.view(a)||jsonb_build_object('replayed',false,'execution',erp_fiscal_reconciliation.execution(a,c));end$$;
create function public.erp_fiscal_protocol_use(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_request_hash text,p_request_size integer)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;v jsonb;begin perform erp_a1.access(p_user_id);a:=erp_fiscal_reconciliation.require_profile(p_attempt_id,'sefaz-sp-protocol-homologation-v1',false);v:=erp_fiscal_reconciliation.use_core(p_user_id,p_attempt_id,p_lease_id,p_request_hash,p_request_size);v:=v||erp_fiscal_reconciliation.flags('sefaz-sp-protocol-homologation-v1');return v;end$$;
create function public.erp_fiscal_protocol_finish(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_response_hash text,p_response_size integer,p_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;v jsonb;begin perform erp_a1.access(p_user_id);a:=erp_fiscal_reconciliation.require_profile(p_attempt_id,'sefaz-sp-protocol-homologation-v1',false);if p_evidence->>'origin' is distinct from 'operational' then raise exception 'reconciliation_profile_conflict' using errcode='40001';end if;v:=erp_fiscal_reconciliation.finish_core(p_user_id,p_attempt_id,p_lease_id,p_response_hash,p_response_size,p_evidence);if p_evidence#>>'{transport,attempt_id}' is distinct from a.id::text or p_evidence#>>'{transport,client,certificate_fingerprint}' is distinct from a.certificate_fingerprint or p_evidence#>>'{transport,endpoint_id}' is distinct from (case a.model when '55' then 'sp-nfe-protocol-homologation' else 'sp-nfce-protocol-homologation' end) or (p_evidence#>>'{transport,response_size}')::integer<>p_response_size or (p_evidence#>>'{transport,received_at}')::timestamptz<a.used_at or (p_evidence#>>'{transport,received_at}')::timestamptz>clock_timestamp()+interval'5 seconds' then raise exception 'reconciliation_transport_conflict' using errcode='40001';end if;
 perform 1 from storage.objects where bucket_id='brufap-fiscal-artifacts' and name='reconciliation/'||a.id::text||'/observations/'||a.request_hash||'.json' and metadata->>'size'=p_evidence->>'transport_receipt_size' and metadata->>'mimetype'='application/octet-stream' for share;
 if not found then raise exception 'reconciliation_transport_receipt_missing' using errcode='40001';end if;return v;end$$;
create function public.erp_fiscal_protocol_fail(p_user_id uuid,p_attempt_id uuid,p_lease_id uuid,p_error_code text)returns jsonb language plpgsql security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;v jsonb;begin perform erp_a1.access(p_user_id);a:=erp_fiscal_reconciliation.require_profile(p_attempt_id,'sefaz-sp-protocol-homologation-v1',false);v:=erp_fiscal_reconciliation.fail_core(p_user_id,p_attempt_id,p_lease_id,p_error_code);return v;end$$;
create function public.erp_fiscal_protocol_command(p_user_id uuid,p_command_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$declare a erp_fiscal_reconciliation.attempt;v jsonb;begin perform erp_a1.access(p_user_id);a:=erp_fiscal_reconciliation.require_profile(p_command_id,'sefaz-sp-protocol-homologation-v1',true);v:=erp_fiscal_reconciliation.command_core(p_user_id,p_command_id);v:=v||jsonb_build_object('recoverable_by_actor',a.actor=p_user_id and a.used_at is not null and a.state in('dispatched','uncertain'));return v;end$$;
create or replace function public.erp_fiscal_reconciliation_history(p_user_id uuid,p_candidate_id uuid,p_limit integer default 25,p_before bigint default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$declare items jsonb;more boolean;begin
 perform erp_fiscal_reconciliation.source(p_user_id,p_candidate_id);if p_limit is null or p_limit not between 1 and 25 or(p_before is not null and p_before<1)then raise exception'reconciliation_page_invalid'using errcode='22023';end if;
 select coalesce(jsonb_agg((erp_fiscal_reconciliation.view(a)-'recovery')order by a.ordinal desc),'[]'::jsonb)into items from(select *from erp_fiscal_reconciliation.attempt where profile='synthetic-protocol-reconciliation-v1' and candidate_id=p_candidate_id and(p_before is null or ordinal<p_before)order by ordinal desc limit p_limit)a;
 more:=jsonb_array_length(items)=p_limit and exists(select 1 from erp_fiscal_reconciliation.attempt where profile='synthetic-protocol-reconciliation-v1' and candidate_id=p_candidate_id and ordinal<(items->-1#>>'{receipt,ordinal}')::bigint);
 return erp_fiscal_reconciliation.flags()||jsonb_build_object('read_only',true,'candidate_id',p_candidate_id,'items',items,'limit',p_limit,'has_more',more,'next_cursor',case when more then items->-1#>>'{receipt,ordinal}'else null end);end$$;
create function public.erp_fiscal_protocol_history(p_user_id uuid,p_candidate_id uuid,p_limit integer default 25,p_before bigint default null)returns jsonb language plpgsql stable security definer set search_path=pg_catalog as $$declare items jsonb;more boolean;begin
 perform erp_fiscal_reconciliation.source(p_user_id,p_candidate_id);if p_limit is null or p_limit not between 1 and 25 or(p_before is not null and p_before<1)then raise exception'reconciliation_page_invalid'using errcode='22023';end if;
 select coalesce(jsonb_agg(((erp_fiscal_reconciliation.view(a)-'recovery')||jsonb_build_object('recoverable_by_actor',a.actor=p_user_id and a.used_at is not null and a.state in('dispatched','uncertain')))order by a.ordinal desc),'[]'::jsonb)into items from(select *from erp_fiscal_reconciliation.attempt where profile='sefaz-sp-protocol-homologation-v1' and candidate_id=p_candidate_id and(p_before is null or ordinal<p_before)order by ordinal desc limit p_limit)a;
 more:=jsonb_array_length(items)=p_limit and exists(select 1 from erp_fiscal_reconciliation.attempt where profile='sefaz-sp-protocol-homologation-v1' and candidate_id=p_candidate_id and ordinal<(items->-1#>>'{receipt,ordinal}')::bigint);
 return erp_fiscal_reconciliation.flags('sefaz-sp-protocol-homologation-v1')||jsonb_build_object('read_only',true,'candidate_id',p_candidate_id,'items',items,'limit',p_limit,'has_more',more,'next_cursor',case when more then items->-1#>>'{receipt,ordinal}'else null end);end$$;
revoke all on all functions in schema erp_fiscal_reconciliation from public,anon,authenticated,service_role;
revoke all on function public.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer) from public,anon,authenticated;
grant execute on function public.erp_fiscal_reconciliation_use(uuid,uuid,uuid,text,integer) to service_role;
revoke all on function public.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb) from public,anon,authenticated;
grant execute on function public.erp_fiscal_reconciliation_finish(uuid,uuid,uuid,text,integer,jsonb) to service_role;
revoke all on function public.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.erp_fiscal_reconciliation_fail(uuid,uuid,uuid,text) to service_role;
revoke all on function public.erp_fiscal_reconciliation_command(uuid,uuid) from public,anon,authenticated;
grant execute on function public.erp_fiscal_reconciliation_command(uuid,uuid) to service_role;
revoke all on function public.erp_fiscal_protocol_use(uuid,uuid,uuid,text,integer) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_use(uuid,uuid,uuid,text,integer) to service_role;
revoke all on function public.erp_fiscal_protocol_finish(uuid,uuid,uuid,text,integer,jsonb) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_finish(uuid,uuid,uuid,text,integer,jsonb) to service_role;
revoke all on function public.erp_fiscal_protocol_fail(uuid,uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_fail(uuid,uuid,uuid,text) to service_role;
revoke all on function public.erp_fiscal_protocol_command(uuid,uuid) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_command(uuid,uuid) to service_role;
revoke all on function public.erp_fiscal_protocol_begin(uuid,uuid,uuid,text,integer,integer,boolean) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_begin(uuid,uuid,uuid,text,integer,integer,boolean) to service_role;
revoke all on function public.erp_fiscal_protocol_history(uuid,uuid,integer,bigint) from public,anon,authenticated;
grant execute on function public.erp_fiscal_protocol_history(uuid,uuid,integer,bigint) to service_role;
commit;
